pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(address _recipient) public {
        // Record owner before call
        address ownerBefore = c.owner();
        // Drive call (only owner can call; we are owner from setUp)
        (bool success, ) = address(c).call(abi.encodeWithSignature("withdrawAll(address)", _recipient));
        // Ignore success/failure – just check owner after
        address ownerAfter = c.owner();
        assertTrue(ownerAfter == ownerBefore, "Owner changed after withdrawAll");
    }
}

